implementation:
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/spinlock.h>
#include <linux/wait.h>
#include <linux/usb.h>

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp)
{
    struct hid_gadget_request *req;
    ssize_t bytes_written = 0;
    int ret = 0;

    /* Check if the user buffer is accessible */
    if (!access_ok(VERIFY_READ, buffer, count)) {
        return -EFAULT;
    }

    spin_lock(&hid_gadget_lock);

    /* Wait until a write can be initiated */
    while (hid_gadget_write_pending) {
        ret = wait_event_interruptible(hid_gadget_write_wait, !hid_gadget_write_pending);
        if (ret < 0) {
            spin_unlock(&hid_gadget_lock);
            return ret;
        }
    }

    /* Mark write as pending to prevent concurrent writes */
    hid_gadget_write_pending = true;
    spin_unlock(&hid_gadget_lock);

    /* Allocate a request structure for the data to be sent */
    req = hid_gadget_request_alloc();
    if (!req) {
        hid_gadget_write_pending = false;
        return -ENOMEM;
    }

    /* Copy data from user buffer to the request structure */
    if (copy_from_user(req->data, buffer, count)) {
        hid_gadget_request_free(req);
        hid_gadget_write_pending = false;
        return -EFAULT;
    }

    req->length = count;

    /* Queue the request for transmission over USB */
    ret = hid_gadget_queue_request(req);
    if (ret < 0) {
        hid_gadget_request_free(req);
        hid_gadget_write_pending = false;
        return ret;
    }

    bytes_written = count;

    /* Wake up any processes waiting on the write queue */
    wake_up_interruptible(&hid_gadget_write_wait);

    return bytes_written;
}
